import type { ReactNode } from 'react'
import { useId, useState } from 'react'
import './styles.css'

export interface SidebarItem {
  value: string
  label: ReactNode
}

export interface SidebarProps {
  /** Accessible name of the navigation landmark. */
  label: string
  items: SidebarItem[]
  header?: ReactNode
  activeValue?: string
  onSelect?: (value: string) => void
  /** Show the collapse toggle (tablet pattern). */
  collapsible?: boolean
  collapsed?: boolean
  defaultCollapsed?: boolean
  onCollapsedChange?: (collapsed: boolean) => void
  /** Toggle accessible name when collapsed. */
  expandLabel?: string
  /** Toggle accessible name when expanded. */
  collapseLabel?: string
  className?: string
}

export function Sidebar({
  label,
  items,
  header,
  activeValue,
  onSelect,
  collapsible = false,
  collapsed,
  defaultCollapsed = false,
  onCollapsedChange,
  expandLabel = 'Expand sidebar',
  collapseLabel = 'Collapse sidebar',
  className,
}: SidebarProps) {
  const [internalCollapsed, setInternalCollapsed] = useState(defaultCollapsed)
  const isCollapsed = collapsed ?? internalCollapsed
  const navId = useId()

  function requestCollapsedChange(next: boolean) {
    if (collapsed === undefined) setInternalCollapsed(next)
    onCollapsedChange?.(next)
  }

  const classes = [
    'cu-sidebar',
    isCollapsed && 'cu-sidebar--collapsed',
    className,
  ]
    .filter(Boolean)
    .join(' ')

  return (
    <aside
      className={classes}
      aria-label={label}
      data-ai-role="sidebar"
      data-ai-intent="navigate-sections"
      data-ai-state={isCollapsed ? 'collapsed' : 'expanded'}
    >
      {header ? <div className="cu-sidebar__header">{header}</div> : null}
      <nav id={navId} className="cu-sidebar__nav" aria-label={label}>
        <ul className="cu-sidebar__list">
          {items.map((item) => (
            <li key={item.value} className="cu-sidebar__entry">
              <button
                type="button"
                className="cu-sidebar__item"
                aria-current={activeValue === item.value ? 'page' : undefined}
                aria-label={typeof item.label === 'string' ? item.label : undefined}
                onClick={() => onSelect?.(item.value)}
              >
                <span className="cu-sidebar__label">{item.label}</span>
              </button>
            </li>
          ))}
        </ul>
      </nav>
      {collapsible ? (
        <button
          type="button"
          className="cu-sidebar__toggle"
          aria-expanded={!isCollapsed}
          aria-controls={navId}
          aria-label={isCollapsed ? expandLabel : collapseLabel}
          onClick={() => requestCollapsedChange(!isCollapsed)}
        >
          <span aria-hidden="true" className="cu-sidebar__toggle-icon" data-direction={isCollapsed ? 'expand' : 'collapse'}>
            <svg viewBox="0 0 24 24" className="cu-sidebar__toggle-svg">
              <path
                d={isCollapsed ? 'M9 6l6 6-6 6' : 'M15 6l-6 6 6 6'}
                fill="none"
                stroke="currentColor"
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
              />
            </svg>
          </span>
          <span className="cu-sidebar__label">{isCollapsed ? expandLabel : collapseLabel}</span>
        </button>
      ) : null}
    </aside>
  )
}

/*
 * Phase 5 container-query whitelist member: the sidebar is its own query
 * container, so a narrow host slot (e.g. the 12rem tablet column in
 * app-shell) collapses it to a rail without any viewport media query.
 */
.cu-sidebar {
  display: flex;
  flex-direction: column;
  gap: var(--cu-space-2);
  inline-size: 16rem;
  min-block-size: 100%;
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-2);
  border-inline-end: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
  background: var(--cu-color-background-subtle, var(--cu-color-background-default));
  color: var(--cu-color-fg-default);
  container-name: sidebar;
  container-type: inline-size;
}

.cu-sidebar--collapsed {
  inline-size: 4.5rem;
}

.cu-sidebar__header {
  padding-block: var(--cu-space-1);
  padding-inline: var(--cu-space-2);
  font-weight: 700;
}

.cu-sidebar__nav {
  flex: 1;
  overflow: auto;
}

.cu-sidebar__list {
  display: flex;
  flex-direction: column;
  gap: var(--cu-space-1);
  list-style: none;
  margin: 0;
  padding: 0;
}

.cu-sidebar__item {
  display: flex;
  align-items: center;
  gap: var(--cu-space-2);
  inline-size: 100%;
  min-block-size: var(--cu-touch-target-min);
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-2);
  border: none;
  border-radius: var(--cu-radius-sm);
  background: transparent;
  color: var(--cu-color-fg-default);
  font: inherit;
  text-align: start;
  cursor: pointer;
}

.cu-sidebar__item[aria-current='page'] {
  background: color-mix(in srgb, var(--cu-color-palette-brand) 10%, var(--cu-color-background-default));
  color: var(--cu-color-palette-brand);
  font-weight: 700;
}

.cu-sidebar__item:focus-visible,
.cu-sidebar__toggle:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 3px;
}

@media (hover: hover) {
  .cu-sidebar__item:hover:not([aria-current='page']),
  .cu-sidebar__toggle:hover {
    background: color-mix(in srgb, var(--cu-color-background-default) 92%, var(--cu-color-palette-brand));
  }
}

.cu-sidebar__toggle {
  display: flex;
  align-items: center;
  gap: var(--cu-space-2);
  min-block-size: var(--cu-touch-target-min);
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-2);
  border: var(--cu-border-width-default, 1px) solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-sm);
  background: transparent;
  color: var(--cu-color-fg-default);
  font: inherit;
  cursor: pointer;
}

.cu-sidebar__toggle-icon {
  display: inline-flex;
  inline-size: 1em;
  block-size: 1em;
  flex: none;
}

.cu-sidebar__toggle-svg {
  inline-size: 100%;
  block-size: 100%;
}

/* Directional affordance: the chevron mirrors under RTL (U6). */
[dir='rtl'] .cu-sidebar__toggle-icon {
  transform: scaleX(-1);
}

/*
 * Explicit collapsed state and container-driven rail (host slot <= 12rem,
 * e.g. the app-shell tablet column) both hide labels; items keep their
 * aria-label and stay keyboard/touch reachable at >= 44px.
 */
.cu-sidebar--collapsed .cu-sidebar__label {
  display: none;
}

.cu-sidebar--collapsed .cu-sidebar__item,
.cu-sidebar--collapsed .cu-sidebar__toggle {
  justify-content: center;
}

@container (max-width: 12rem) {
  .cu-sidebar__label {
    display: none;
  }

  .cu-sidebar__item,
  .cu-sidebar__toggle {
    justify-content: center;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cu-sidebar,
  .cu-sidebar__item,
  .cu-sidebar__toggle {
    transition-duration: 0.01ms;
  }
}
